import{z as s,x as A,o as t,c as d,q as l,j as n,D as e,d as r,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"公司债 OTC 询价","description":"","frontmatter":{"title":"公司债 OTC 询价","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/corporate-bond-otc.md","filePath":"quant/corporate-bond-otc.md","lastUpdated":1791063341000}'),p={name:"quant/corporate-bond-otc.md"};function C(u,a,m,h,D,T){const B=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="公司债-otc-询价" tabindex="-1">公司债 OTC 询价 <a class="header-anchor" href="#公司债-otc-询价" aria-label="Permalink to &quot;公司债 OTC 询价&quot;">​</a></h1><div class="epigraph"><p>询价市场里，价格是对特定对手、特定数量、特定时刻的回复，不是对全市场有效的报价。打印告诉你有人成交了，不问你能否在同一价格再成交。</p><footer>—— 据 Duffie, Garleanu and Pedersen 对 OTC 搜索与议价的理论；对照 Bessembinder 与 Harris 对公司债经销商市场的经验描述</footer></div><p><a href="/quant/bond-liquidity-trace">债券流动性与 TRACE</a>从打印估计成本。本课的缺口是协议：公司债如何在 OTC 里成交——请求报价（RFQ）、经销商存货、客户关系、电子询价平台——以及为什么股票式的 NBBO 在这里没有对象。Duffie、Garleanu 与 Pedersen 把 OTC 写成搜索与议价：找到对手要时间，议价力决定加价。期限结构课序在本课收束；执行时要把 RFQ 当成订单类型，而不是当成「慢一点的市价单」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股票连续竞价：你看到 BBO，选择吃或挂。公司债：你向一群经销商发送「买 2 百万面值的某 CUSIP」，收到若干回复，选一个成交，其余作废。回复可以只对你有效、只对该数量有效、只在几十秒内有效。TRACE 随后打印一个价格，其他客户并不能点击该价格。流动性的状态变量是：你的网络有多宽、经销商库存是否碰巧在你的方向、以及你是否被识别成知情或被识别成索引再平衡流量。</p><p><span class="marginnote">术语翻译：RFQ（请求报价）就是「拿着需求挨家问价」——你发一个买多少的请求，几家经销商各自回「我愿在这个价、这个量、这几秒内接」。回复只对你有效，不是全市场报价；没点掉的单子一律作废。</span></p><p>缺口是把「有成交价」与「可执行报价」分开。用昨日 TRACE 均价当今日可交易价，忽略了询价的搜索成本和经销商对你的定价歧视。评级下调日，打印稀疏，询价回复变宽或拒绝回复——这是流动性消失，不是数据缺失。</p><h3 id="rfq、点击成交与语音并非同一市场" tabindex="-1">RFQ、点击成交与语音并非同一市场 <a class="header-anchor" href="#rfq、点击成交与语音并非同一市场" aria-label="Permalink to &quot;RFQ、点击成交与语音并非同一市场&quot;">​</a></h3><p>电子平台把 RFQ 标准化，但仍是询价。部分平台提供可点击的指示性报价，深度通常小于机构目标规模。大额、冷门、复杂条款仍走语音。混在一起估一个价差，会把电子小单的窄加价当成市场，把语音大单当成异常。方法是按渠道和规模分层，与 TRACE 规模分层对齐。</p><p><span class="marginnote">经销商知道你是否同时在向五家询价（部分平台会显示或被推断）。广泛询价改善竞争，也泄露需求。搜索理论里这是信息公开与议价力的权衡，不是执行技巧清单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行会计以 RFQ 生命周期为对象：发送时刻、回复数量、最优回复相对基准的偏离、成交与否、成交后 TRACE 打印延迟、以及未成交时的机会成本（用随后打印或随后成功 RFQ 估价）。这对应股票里的实施缺口，但没有公开中点，参照改用基准曲线。填成率与回复率是流动性的一等指标，比「平均打印价差」更接近决策。</p><p>定价研究若用 TRACE 收盘合成价，应明白该价是谁的成交：零售小单与机构大单的加价不同，Edwards–Harris–Piwowar 已强调规模效应。指数纳入使许多账户同时询同一只券，经销商存货同向，加价上升——这是拥挤在 OTC 上的版本，不是股票 ADV 参与率。</p><p><span class="marginnote">数字实例：一只投资级债的中间价对应国债利差 100bp。5 万美元的零售小单可能收到 110bp 的买价，同方向 500 万的机构询价可能被回 125bp——同一时刻、同一只券，「市场价」因你的规模与身份而异，这就是搜索摩擦的直接读数。</span></p><h3 id="存货、对冲与「两张簿」" tabindex="-1">存货、对冲与「两张簿」 <a class="header-anchor" href="#存货、对冲与「两张簿」" aria-label="Permalink to &quot;存货、对冲与「两张簿」&quot;">​</a></h3><p>经销商接单后，用国债期货、CDS、股票或已有库存对冲。报价宽度含预期对冲成本与无法对冲的跳跃风险。可转债课已经说明信用与股票相关；普通公司债的经销商对冲同样跨市场。客户看到的 RFQ 回复，已经含这些对冲摩擦。把回复价相对国债利差的偏离全部叫做「公司债 alpha」，会把经销商存货周期当成信号。</p><p><span class="marginnote">常见误区：初学者把 TRACE 打印当成「市价」，以为能按昨天的成交价估今天。打印只是别人成交的记录；评级下调日打印稀疏、回复变宽，那是流动性消失，不是数据坏了。</span></p><p>一条 RFQ 回复价里都装了什么：</p>',18)),(t(),n(i,null,{default:e(()=>[o(B,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%AE%A2%E6%88%B7%20RFQ%3A%20%E4%B9%B0%202%20%E7%99%BE%E4%B8%87%E9%9D%A2%E5%80%BC%22%5D%20--%3E%20B%5B%22%E7%BB%8F%E9%94%80%E5%95%86%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20B%20--%3E%20C%5B%22%E4%B8%AD%E9%97%B4%E4%BB%B7%3A%20%E5%9B%BD%E5%80%BA%20%2B%20%E4%BF%A1%E7%94%A8%E5%88%A9%E5%B7%AE%22%5D%0A%20%20B%20--%3E%20D%5B%22%E5%8A%A0%E4%BB%B7%3A%20%E8%AE%AE%E4%BB%B7%E5%8A%9B%20%C3%97%20%E6%90%9C%E7%B4%A2%E6%91%A9%E6%93%A6%22%5D%0A%20%20B%20--%3E%20E%5B%22%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%3A%20%E6%9C%9F%E8%B4%A7%20%2F%20CDS%20%E5%8F%AF%E5%BE%97%E6%80%A7%22%5D%0A%20%20B%20--%3E%20F%5B%22%E5%AD%98%E8%B4%A7%E6%96%B9%E5%90%91%3A%20%E5%90%8C%E5%90%91%E6%8C%81%E8%B4%A7%E5%88%99%E5%8E%8B%E4%BB%B7%22%5D%0A%20%20C%20--%3E%20G%5B%22%E5%9B%9E%E5%A4%8D%3A%20%E4%BB%B7%20%2F%20%E9%87%8F%20%2F%20%E6%97%B6%E6%95%88%22%5D%0A%20%20D%20--%3E%20G%0A%20%20E%20--%3E%20G%0A%20%20F%20--%3E%20G%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"OTC 的匹配靠搜索：Duffie–Garleanu–Pedersen 的模型里，对手到达是随机的，议价分享剩余。电子化提高到达强度，加价下降，但异质债券不会收敛到股票式连续簿——契约太多，每只券的自然对手太少。TRACE 事后透明改变议价的信息集：客户知道昨天的打印，经销商不能再对完全不透明的历史成交要价。事前仍不透明：你不知道此刻谁愿意在什么价位拿多少存货。",-1)),a[5]||(a[5]=E("p",null,"与集合竞价的对照：收盘拍卖是多边、同时、同一价格。RFQ 是双边、序贯、价格歧视。不要把债券「收盘价」理解成一场公开集合的出清价，它常常只是某种合成或最后打印。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},[E("a",{href:"/quant/roll-model"},"Roll"),r(" 的买卖回跳假定同一市场来回成交。OTC 里相邻两笔可能是完全不同的客户与经销商，协方差不是价差。债券 Roll 估计要非常谨慎，优先用配对经销商买卖。")])],-1)),(t(),n(i,null,{default:e(()=>[o(B,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TB%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E9%9C%80%E6%B1%82%22%5D%20--%3E%20R%5B%22RFQ%20%E5%8F%91%E9%80%81%E5%88%B0%E7%BB%8F%E9%94%80%E5%95%86%E7%BD%91%E7%BB%9C%22%5D%0A%20%20R%20--%3E%20V%5B%22%E5%9B%9E%E5%A4%8D%EF%BC%9A%E4%BB%B7%E3%80%81%E9%87%8F%E3%80%81%E6%97%B6%E6%95%88%22%5D%0A%20%20V%20--%3E%20X%5B%22%E9%80%89%E4%B8%80%E6%88%90%E4%BA%A4%22%5D%0A%20%20X%20--%3E%20T%5B%22TRACE%20%E4%BA%8B%E5%90%8E%E6%89%93%E5%8D%B0%22%5D%0A%20%20V%20--%3E%20N%5B%22%E6%97%A0%E5%9B%9E%E5%A4%8D%20%2F%20%E6%8B%92%E7%BB%9D%22%5D%0A%20%20N%20--%3E%20S%5B%22%E6%90%9C%E7%B4%A2%E6%9C%AA%E5%AE%8C%E6%88%90%EF%BC%9A%E5%8F%98%E7%8E%B0%E6%97%B6%E9%97%B4%E6%8B%89%E9%95%BF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h3 id="指示性报价不是可执行回复" tabindex="-1">指示性报价不是可执行回复 <a class="header-anchor" href="#指示性报价不是可执行回复" aria-label="Permalink to &quot;指示性报价不是可执行回复&quot;">​</a></h3><p>平台上的可点击价格往往只对小规模有效。机构目标面值仍要走 RFQ。把可点击价差当市场，会把电子零售层当成整个 OTC。分层渠道是方法，不是修饰。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>美国投资级电子化程度高于高收益和新兴市场债。贷款、CDS 指数与单名 CDS 各有询价惯例。本课不提供如何选择询价家数以获取更好价格的操作建议。监管报告、最佳执行义务因司法管辖而异。下一课程投资组合不再默认「按收盘价调仓」；对债券，调仓是一次 RFQ 过程。</p><p><span class="marginnote">债券「收盘价」常常是合成或最后打印，不是集合出清。指数估值若把该价当成可交易，再平衡冲击会被低估。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OTC 价格是对手特定、数量特定、时效特定的回复，不是 NBBO。</li><li>RFQ 生命周期（回复率、填成、相对基准偏离）才是执行会计。</li><li>电子小单与语音大单必须分层；TRACE 均价不是可点击报价。</li><li>搜索与议价解释加价；事后透明削弱但不消灭信息租金。</li><li>相邻打印的协方差不能直接当 Roll 价差。</li><li>出处：Duffie, Garleanu and Pedersen, <em>Econometrica</em> / RFS 对 OTC 搜索的工作；Edwards, Harris and Piwowar, 2007；Bessembinder 等对经销商市场的经验研究。</li></ul>',7))])}const F=s(p,[["render",C]]);export{f as __pageData,F as default};
